<?php

namespace App\Libraries;

use InvalidArgumentException;

/** References copied from payment confirmations, never generated by the POS. */
final class PaymentReference
{
    public static function rules(): array
    {
        return [
            'cash' => ['label' => 'Reference No.', 'pattern' => '', 'minimum' => 0, 'maximum' => 100, 'inputmode' => 'text',
                'placeholder' => 'Optional for cash', 'help' => 'Cash payments do not need a payment reference.', 'error' => ''],
            // Supported GCash workflow: the customer's merchant QR payment confirmation ID.
            'gcash' => ['label' => 'GCash reference number', 'pattern' => '[0-9]{13}', 'minimum' => 13, 'maximum' => 13, 'inputmode' => 'numeric',
                'placeholder' => '13-digit GCash reference', 'help' => 'Copy the 13-digit transaction reference from the customer’s GCash payment confirmation.',
                'error' => 'Enter the 13-digit GCash payment reference using numbers only.'],
            // Acquirers use different approval/reference lengths; this is an application allowlist.
            'card' => ['label' => 'Card approval / transaction reference', 'pattern' => '(?=.*[A-Za-z0-9])[A-Za-z0-9 ._\/\-]{1,100}', 'minimum' => 1, 'maximum' => 100, 'inputmode' => 'text',
                'placeholder' => 'Approval or reference from terminal receipt', 'help' => 'Copy the approval code or transaction reference from the terminal receipt. Its length depends on the payment provider.',
                'error' => 'Enter the terminal reference using up to 100 letters, numbers, spaces, hyphens, slashes, underscores or dots.'],
        ];
    }

    public static function assertAllowed(string $method, mixed $reference, bool $required = true): string
    {
        $rule = self::rules()[$method] ?? null;
        if ($rule === null) throw new InvalidArgumentException('Select a supported payment method.');
        if ($method === 'cash') return '';
        if ($reference === null && !$required) return '';
        if (!is_string($reference)) throw new InvalidArgumentException('Enter a valid payment reference.');
        $reference = trim($reference);
        if ($reference === '' && !$required) return '';
        if (!preg_match('~^(?:' . $rule['pattern'] . ')$~D', $reference)) throw new InvalidArgumentException($rule['error']);
        return $reference;
    }
}
